/**
 * The Merchandizable demo shop in the prototype. Chart, outcomes and result groups come from
 * merchandizable.json, generated by services/api/scripts/export_catalog.py. This file only looks them
 * up and assembles a response: there are no fit rules here.
 */
import { hostOf } from "@/lib/format";
import type {
  CheckResult,
  CheckView,
  DemoChart,
  FitCheck,
  OptionOut,
  Profile,
} from "../types";
import fixture from "./merchandizable.json";

export type DemoProduct = (typeof fixture.products)[number];
type Variant = { group: string; fit: unknown };

export const DEMO_SHOP = fixture.shop;
export const DEMO_CHART = fixture.chart as DemoChart;
export const DEMO_PRODUCTS: DemoProduct[] = fixture.products;
export const PERSONAL_SAMPLES = fixture.personal_samples;

const PERSONAL_NOTE =
  "This browser prototype can't compare your own measurements, which happens in the Python engine. Try sample measurements to see its results.";

function pageKey(url: string): string {
  const path = new URL(url.includes("://") ? url : `https://${url}`).pathname;
  return `${hostOf(url)}${path.replace(/\/$/, "")}`;
}

export function demoProductForUrl(url: string): DemoProduct | undefined {
  try {
    const key = pageKey(url);
    return DEMO_PRODUCTS.find((p) => pageKey(p.input_url) === key);
  } catch {
    return undefined;
  }
}

function quickVariant(product: DemoProduct, profile: Profile | null): Variant {
  const sizes: Record<string, string | undefined> = profile?.quick_sizes ?? {};
  const size = product.fit_category ? sizes[product.fit_category] : undefined;
  const variants: Record<string, Variant> = product.quick_fit;
  return variants[size ?? "none"];
}

function ownMeasurementsVariant(product: DemoProduct): Variant {
  const { group, fit } = product.personal_fit;
  return { group, fit: { ...fit, reasons: [...fit.reasons, PERSONAL_NOTE] } };
}

function variantFor(
  product: DemoProduct,
  profile: Profile | null,
  sampleId?: string,
): Variant {
  const samples: Record<string, Variant> = product.sample_fit;
  if (sampleId && samples[sampleId]) return samples[sampleId];
  return profile?.fit_mode === "personal_fit"
    ? ownMeasurementsVariant(product)
    : quickVariant(product, profile);
}

function hiddenSummary(option: OptionOut): CheckResult["hidden_mismatches"] {
  const reasons = option.fit_check.reasons ?? [];
  return {
    count: 1,
    reasons: [`${option.seller.name}: ${reasons.join(" ")}`],
  };
}

function demoDetails(product: DemoProduct, sampleId?: string): CheckView["demo"] {
  const sample = PERSONAL_SAMPLES.find((s) => s.id === sampleId);
  return {
    shop_name: DEMO_SHOP.name,
    sold_sizes: product.sold_sizes,
    chart: DEMO_CHART,
    sample_label: sample?.label ?? null,
  };
}

/** The same response shape as GET /v1/checks/{id}, with the demo chart added. */
export function buildDemoResult(
  product: DemoProduct,
  profile: Profile | null,
  meta: { id: string; url: string; createdAt: string; sampleId?: string },
): CheckView {
  const { group, fit } = variantFor(product, profile, meta.sampleId);
  const check = fit as FitCheck;
  const option = { ...product.option, fit_check: check } as OptionOut;
  const hidden = group === "hidden";
  return {
    id: meta.id,
    status: "done",
    current_step: null,
    input_url: meta.url,
    created_at: meta.createdAt,
    completed_at: new Date().toISOString(),
    error: null,
    unit: profile?.unit ?? "cm",
    product: {
      name: product.name,
      brand: null,
      category: product.product_type_label,
      attributes: {},
      image_url: null,
    },
    selected_size: hidden ? null : (check.size_label ?? null),
    fit_mode_used: check.mode ?? null,
    matches: group === "matches" ? [option] : [],
    uncertain: group === "uncertain" ? [option] : [],
    hidden_mismatches: hidden ? hiddenSummary(option) : { count: 0, reasons: [] },
    demo: demoDetails(product, meta.sampleId),
  };
}
